from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days: int = loan_days
        self.daily_fine: float = daily_fine

        # Track catalog of books and current borrow status
        self._books: set[str] = set()
        # book_id -> (user, borrow_date)
        self._borrowed_books: dict[str, tuple[str, date]] = {}
        # user -> set of book_ids currently borrowed
        self._user_books: dict[str, set[str]] = {}
        # user -> accumulated unpaid fine
        self._user_fines: dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Book {book_id} is not in the library catalog.")
        if book_id in self._borrowed_books:
            raise ValueError(f"Book {book_id} is already borrowed.")

        current_borrowed = self._user_books.get(user, set())
        has_unpaid_fines = self.unpaid_fines(user) > 0

        # Requirement 1: A user with unpaid fines may hold at most one book at a time.
        if has_unpaid_fines and len(current_borrowed) >= 1:
            raise ValueError(
                f"User {user} has unpaid fines and cannot borrow more than one book at a time."
            )

        self._borrowed_books[book_id] = (user, day)
        self._user_books.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        # Requirement 2: Returning a book that the user has not borrowed raises ValueError.
        if book_id not in self._borrowed_books or self._borrowed_books[book_id][0] != user:
            raise ValueError(f"User {user} has not borrowed book {book_id}.")

        _, borrow_date = self._borrowed_books.pop(book_id)
        self._user_books[user].remove(book_id)

        due_date = borrow_date + timedelta(days=self.loan_days)
        late_weekdays = 0

        # Requirement 3 & 4: Days of delay strictly after due date, excluding weekends (Sat/Sun).
        current_date = due_date + timedelta(days=1)
        while current_date <= day:
            # weekday(): Monday is 0, Sunday is 6; 5 and 6 are Saturday and Sunday.
            if current_date.weekday() < 5:
                late_weekdays += 1
            current_date += timedelta(days=1)

        fine = late_weekdays * self.daily_fine
        self._user_fines[user] = self._user_fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._user_fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self._user_fines[user] = 0.0
```

